use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Gen {
    kind: string,
    a: int,
    b: int,
    h: int,
}

impl Shape for Gen {
    fn name(self) -> string {
        self.kind.clone()
    }
    fn corners(self) -> int {
        if self.kind == "rtri" { 3 } else { 4 }
    }
    fn double_area(self) -> int {
        if self.kind == "square" {
            2 * self.a * self.a
        } else if self.kind == "rect" {
            2 * self.a * self.b
        } else if self.kind == "rtri" {
            self.a * self.b
        } else {
            (self.a + self.b) * self.h
        }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total = 0
    let mut best = -1
    let mut best_name = ""
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if parts.len() == 0 { continue }
        let n: int = parts.len() as int
        let a: int = if n > 1 { parts[1].parse::<int>().unwrap_or(0) } else { 0 }
        let b: int = if n > 2 { parts[2].parse::<int>().unwrap_or(0) } else { 0 }
        let h: int = if n > 3 { parts[3].parse::<int>().unwrap_or(0) } else { 0 }
        let s = Gen { kind: parts[0].clone(), a: a, b: b, h: h }
        let d = s.double_area()
        println("${s.name()} corners=${s.corners()} area2=${d}")
        total += d
        if d > best {
            best = d
            best_name = s.name()
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

